extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var star := instantiate_scene("res://star.tscn") as Sprite2D
	if not check("star_inst", star != null, "La scena star.tscn deve istanziarsi correttamente"):
		return

	var item_types = star.get("ITEM_TYPES")
	if not check("dict_exists", typeof(item_types) == TYPE_DICTIONARY, "ITEM_TYPES deve essere un Dictionary in star.gd"):
		return

	check("star_key", "star" in item_types, "ITEM_TYPES deve contenere la chiave 'star'")
	check("gold_star_key", "gold_star" in item_types, "ITEM_TYPES deve contenere la chiave 'gold_star'")
	check("rock_key", "rock" in item_types, "ITEM_TYPES deve contenere la chiave 'rock'")

	if "gold_star" in item_types and typeof(item_types["gold_star"]) == TYPE_DICTIONARY:
		check("gold_points", item_types["gold_star"].get("points") == 50, "La stella d'oro deve valere 50 punti")

	if "rock" in item_types and typeof(item_types["rock"]) == TYPE_DICTIONARY:
		check("rock_points", item_types["rock"].get("points") == -20, "Il sasso deve avere points pari a -20")

	check("has_apply", has_function(star, "apply_item_type"), "star.gd deve definire la funzione apply_item_type")

	call_if_exists(star, "apply_item_type", ["rock"])
	var points_rock = get_prop(star, "points")
	var speed_rock = get_prop(star, "fall_speed")
	check("apply_rock_points", points_rock == -20, "apply_item_type('rock') deve impostare points a -20")
	check("apply_rock_speed", speed_rock == 220.0, "apply_item_type('rock') deve impostare fall_speed a 220.0")
	check("apply_rock_color", star.modulate == Color.GRAY, "apply_item_type('rock') deve impostare modulate su Color.GRAY")

	call_if_exists(star, "apply_item_type", ["gold_star"])
	var points_gold = get_prop(star, "points")
	check("apply_gold_points", points_gold == 50, "apply_item_type('gold_star') deve impostare points a 50")
	check("apply_gold_color", star.modulate == Color.ORANGE, "apply_item_type('gold_star') deve impostare modulate su Color.ORANGE")

